<?php
require 'config/database.php';require 'includes/functions.php';$title='Dashboard';
$products=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE is_archived=0")->fetchColumn();
$units=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM products WHERE is_archived=0")->fetchColumn();
$value=(float)$pdo->query("SELECT COALESCE(SUM(quantity*unit_cost),0) FROM products WHERE is_archived=0")->fetchColumn();
$low=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE is_archived=0 AND quantity<=reorder_level")->fetchColumn();
$recent=$pdo->query("SELECT t.*,p.name,p.sku FROM stock_transactions t JOIN products p ON p.id=t.product_id ORDER BY t.created_at DESC,t.id DESC LIMIT 7")->fetchAll();
$items=$pdo->query("SELECT * FROM products WHERE is_archived=0 AND quantity<=reorder_level ORDER BY quantity LIMIT 5")->fetchAll();require 'includes/header.php';?>
<section class="heading"><div><small>OVERVIEW</small><h1>Good day, Manager ✦</h1><p>Here's what's happening with your inventory today.</p></div><a class="btn primary" href="product_form.php">＋ Add new product</a></section>
<section class="metrics"><article><label>Total products</label><b><?=$products?></b><small>Active catalog items</small><i class="ico blue">▤</i></article><article><label>Units in stock</label><b><?=number_format($units)?></b><small>Across active products</small><i class="ico violet">▦</i></article><article><label>Inventory value</label><b class="value"><?=money($value)?></b><small>Based on unit cost</small><i class="ico green">₦</i></article><article><label>Low stock alerts</label><b><?=$low?></b><small class="<?=$low?'warn':''?>"><?=$low?'Needs attention soon':'Stock levels look good'?></small><i class="ico orange">!</i></article></section>
<section class="columns"><article class="panel"><div class="panel-head"><div><h2>Recent stock activity</h2><p>Latest movements across your inventory</p></div><a href="transactions.php">View all →</a></div><?php if(!$recent):?><div class="empty"><b>No transactions yet</b><p>Stock movements appear here when recorded.</p><a class="btn secondary" href="transactions.php">Record transaction</a></div><?php else:?><div class="scroll"><table><thead><tr><th>PRODUCT</th><th>TYPE</th><th>QUANTITY</th><th>DATE</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['sku'])?></small></td><td><span class="pill <?=$r['type']==='IN'?'good':'bad'?>"><?=$r['type']==='IN'?'Stock in':'Stock out'?></span></td><td class="<?=$r['type']==='IN'?'positive':'negative'?>"><?=$r['type']==='IN'?'+':'−'?><?=$r['quantity']?></td><td><?=date('M j, Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article>
<article class="panel"><div class="panel-head"><div><h2>Low stock items</h2><p>At or below reorder level</p></div><span class="pill bluepill"><?=count($items)?></span></div><?php if(!$items):?><div class="empty">You're all stocked up.</div><?php endif;?><?php foreach($items as $p):$pct=$p['reorder_level']?min(100,round($p['quantity']/$p['reorder_level']*100)):0;?><div class="stock"><div><b><?=e($p['name'])?></b><strong><?=$p['quantity']?> left</strong></div><div class="bar"><span style="width:<?=$pct?>%"></span></div><small>Reorder point: <?=$p['reorder_level']?></small></div><?php endforeach;?><a class="manage" href="products.php">Manage products →</a></article></section>
<section class="quick"><div><small>QUICK ACTIONS</small><h2>Keep your stock moving</h2></div><a href="product_form.php"><b class="qicon blue">＋</b><span><strong>Add a product</strong><small>Create a catalog item</small></span>→</a><a href="transactions.php"><b class="qicon violet">⇄</b><span><strong>Record stock movement</strong><small>Receive or issue stock</small></span>→</a><a href="reports.php"><b class="qicon green">▥</b><span><strong>View reports</strong><small>Review inventory</small></span>→</a></section>
<?php require 'includes/footer.php';?>